import 'dart:async';

Future<String> loadTitle(int id) async {
  await Future<void>.delayed(const Duration(milliseconds: 20));
  return 'Document $id';
}

Stream<String> titles(List<int> ids) async* {
  for (final id in ids) {
    yield await loadTitle(id);
  }
}

Future<void> main() async {
  try {
    await for (final title in titles([1, 2, 3])) {
      print(title);
    }
  } on TimeoutException catch (error, stack) {
    print('Timed out: $error\n$stack');
  } finally {
    print('Finished');
  }
}

mixin Named {
  String get name;
  String describe() => 'Item: $name';
}

class Catalog<T extends Object> with Named {
  @override
  final String name;
  final List<T> _items;

  Catalog(this.name, Iterable<T> items) : _items = List.of(items);

  factory Catalog.empty(String name) => Catalog(name, <T>[]);

  int get length => _items.length;
  T operator [](int index) => _items[index];
  void add(T value) => _items.add(value);
}

extension CleanLabel on String {
  String get label => trim().toUpperCase();
}

void main() {
  final catalog = Catalog<String>.empty('Virgo')
    ..add('Design')
    ..add('Cloud Docs');
  print('${catalog.describe()}: ${catalog[0].label}');
}

List<String> labels(List<String>? items, String? featured) => [
  ?featured,
  ...?items,
  if (items?.isEmpty ?? true) 'Untitled',
  for (final item in items ?? <String>[]) item.trim(),
];

Map<String, int> histogram(Iterable<String> words) {
  final counts = <String, int>{};
  for (final word in words) {
    counts.update(word, (value) => value + 1, ifAbsent: () => 1);
  }
  return counts;
}

void main() {
  final values = labels(['Dart', 'Flutter', 'Dart'], null);
  final counts = histogram(values);
  print({for (final MapEntry(:key, :value) in counts.entries) key: value});
}

class User {
  final String name;
  final int age;

  const User(this.name, {required this.age});

  String get greeting => 'Hello, $name!';
}

(String, int) describe(User user) => (user.name, user.age);

void main(List<String> arguments) {
  final user = User(arguments.firstOrNull ?? 'Ada', age: 28);
  final (name, age) = describe(user);

  print(user.greeting);
  print('$name is $age years old.');
}

